    "cases.project_pin.heading": "Περιπτώσεις για ένα έργο",
    "cases.project_pin.picker_label": "Έργο",
    "cases.project_pin.picker_none": "Δεν έχει επιλεγεί έργο",
    "cases.project_pin.show_pinned_only": "Καρφιτσωμένα σε αυτό το έργο",
